import React, { useEffect, useState } from 'react';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import '../styles/global.css';

const API_URL = 'https://utils.statsup.cl/api/get-json/gOAGdMbJfkXR';

const News = () => {
    const [items, setItems] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    useEffect(() => {
        const controller = new AbortController();
        const fetchItems = async () => {
            setLoading(true);
            setError(null);
            try {
                const res = await fetch(API_URL, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({}),
                    signal: controller.signal
                });

                if (!res.ok) throw new Error(`HTTP ${res.status}`);

                const data = await res.json();

                // Expecting an array of { titulo, imagen, cuerpo }
                if (Array.isArray(data)) {
                    setItems(data);
                } else {
                    setError('Respuesta de API en formato inesperado');
                }
            } catch (err) {
                if (err.name !== 'AbortError') {
                    setError(err.message || 'Error al cargar novedades');
                }
            } finally {
                setLoading(false);
            }
        };

        fetchItems();
        return () => controller.abort();
    }, []);

    return (
        <>
            <Navbar />
            <div className="container mt-5">
                <h2 className="text-center mb-4">Últimas Novedades</h2>

                {loading && (
                    <div className="text-center my-4">Cargando novedades...</div>
                )}

                {error && (
                    <div className="alert alert-danger" role="alert">{error}</div>
                )}

                <div className="row">
                    {!loading && items.length === 0 && !error && (
                        <div className="col-12">
                            <p>No hay novedades disponibles.</p>
                        </div>
                    )}

                    {items.map((item, idx) => (
                        <div className="col-md-6 mb-4" key={idx}>
                            <div className="card h-100">
                                {item.imagen && (
                                    <img src={item.imagen} className="card-img-top" alt={item.titulo || 'Imagen'} />
                                )}
                                <div className="card-body d-flex flex-column">
                                    <h5 className="card-title">{item.titulo}</h5>
                                    <p className="card-text">{item.cuerpo}</p>
                                    <div className="mt-auto">
                                        <a href="#" className="btn btn-primary">Ver más</a>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
            <Footer />
        </>
    );
};

export default News;
